// Minimal Canvas Escape game
// Assumes an existing <canvas id="game"></canvas> in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = 400;
  const HEIGHT = canvas.height = 600;

  // Ship state
  const ship = {
    x: 50,
    y: HEIGHT / 2,
    w: 20,
    h: 20,
    vy: 0,
    radius: 10,
  };
  const GRAVITY = 0.4;
  const BOOST = -8;

  // Obstacles
  const obstacles = [];
  const OBSTACLE_SPACING = 1200; // ms
  const OBSTACLE_SPEED = 3;
  let lastObstacle = 0;

  let score = 0;
  let startTime = null;
  let running = true;

  function reset() {
    ship.y = HEIGHT / 2;
    ship.vy = 0;
    obstacles.length = 0;
    lastObstacle = 0;
    score = 0;
    startTime = null;
    running = true;
    requestAnimationFrame(frame);
  }

  function addObstacle() {
    // Random size and vertical position
    const h = 30 + Math.random() * 70;
    const y = Math.random() * (HEIGHT - h);
    obstacles.push({ x: WIDTH, y, w: 20, h });
  }

  function update(dt) {
    // Ship physics
    ship.vy += GRAVITY;
    ship.y += ship.vy;

    // Bounds check (top only, bottom triggers game over)
    if (ship.y < 0) ship.y = 0;
    if (ship.y + ship.h > HEIGHT) running = false;

    // Obstacles movement
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= OBSTACLE_SPEED;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }

    // Collision detection
    for (const o of obstacles) {
      if (
        ship.x < o.x + o.w &&
        ship.x + ship.w > o.x &&
        ship.y < o.y + o.h &&
        ship.y + ship.h > o.y
      ) {
        running = false;
        break;
      }
    }

    // Add new obstacles
    if (Date.now() - lastObstacle > OBSTACLE_SPACING) {
      addObstacle();
      lastObstacle = Date.now();
    }

    // Score is elapsed time in seconds
    if (running) {
      const now = Date.now();
      if (!startTime) startTime = now;
      score = ((now - startTime) / 1000).toFixed(1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);

    // Draw ship (circle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.arc(ship.x + ship.w / 2, ship.y + ship.h / 2, ship.radius, 0, Math.PI * 2);
    ctx.fill();

    // Draw obstacles (rectangles)
    ctx.fillStyle = '#f00';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }

    // Draw score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}s`, 10, 20);

    // Game over message
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2 - 20);
      ctx.font = '18px sans-serif';
      ctx.fillText('Click to restart', WIDTH / 2, HEIGHT / 2 + 20);
    }
  }

  function frame(timestamp) {
    if (!running) {
      draw();
      return; // stop loop
    }
    update(timestamp);
    draw();
    requestAnimationFrame(frame);
  }

  // Input – boost ship upward on any click/tap
  canvas.addEventListener('mousedown', () => (ship.vy = BOOST));
  canvas.addEventListener('touchstart', e => {
    e.preventDefault();
    ship.vy = BOOST;
  });

  // Restart on click after game over
  canvas.addEventListener('click', () => {
    if (!running) reset();
  });

  // Start the game
  requestAnimationFrame(frame);
})();
